// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;

    function setUp() public { c = new Proxy(); }

    // Fuzz the calldata bytes so the fuzzer searches for inputs; the key adversarial factor
    // is that the callee reverts. We deploy a Reverter helper and pass its address as the
    // callee argument. The general rule: for ANY calldata bytes, if the callee reverts,
    // the reference contract's forward must revert; the mutant will not.
    function testFuzz_property(bytes memory payload) public {
        // keep payload arbitrary (wide) but bound its length to a reasonable max to avoid cost
        if (payload.length > 1024) payload = new bytes(1024);

        // deploy a callee that always reverts when called
        Reverter rev = new Reverter();

        // Call c.forward(rev, payload) and observe whether it reverts.
        bool ok;
        try c.forward(address(rev), payload) {
            ok = true;
        } catch {
            ok = false;
        }

        // Assert: reference contract always reverts when callee reverts, so ok must be false for all payloads.
        assertTrue(!ok);
    }
}

// Adversarial callee: always reverts on any call (including plain call / fallback)
contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}
